{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, service_name, metric, count(*) n, round(avg(value),4) avgv, round(max(value),4) maxv FROM normal_metrics WHERE metric='container.cpu.usage' AND service_name='geo' GROUP BY 1,2,3 UNION ALL SELECT 'abnormal', service_name, metric, count(*), round(avg(value),4), round(max(value),4) FROM abnormal_metrics WHERE metric='container.cpu.usage' AND service_name='geo' GROUP BY 1,2,3",
          "claim": "Geo container CPU rose from about 0.003 cores in normal to about 1.56 cores (max 1.60) in the incident, pinned at its limit."
        },
        {
          "kind": "metric",
          "sql": "SELECT CAST(floor(epoch(time)/120) AS BIGINT) b, attr_k8s_pod_name pod, round(avg(value),3) cpu, count(*) n FROM abnormal_metrics WHERE metric='container.cpu.usage' AND service_name='geo' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Geo's single pod sits at roughly 1.6 cores for every two-minute bucket of the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'N' p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,3) avg_ms, round(quantile_cont(duration,0.9)/1e6,3) p90 FROM normal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND attr_span_kind='Server') GROUP BY 1,2,3,4 UNION ALL SELECT 'A', service_name, span_name, attr_span_kind, count(*), round(avg(duration)/1e6,3), round(quantile_cont(duration,0.9)/1e6,3) FROM abnormal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby') OR (service_name='geo' AND attr_span_kind='Server') GROUP BY 1,2,3,4 ORDER BY 2,1",
          "claim": "Geo server and search's client span for geo barely moved (about 0.12 to 0.12 ms and 0.41 ms), so user impact is small."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'N' p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,3) avg_ms FROM normal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY 1,2,3,4 UNION ALL SELECT 'A', service_name, span_name, attr_span_kind, count(*), round(avg(duration)/1e6,3) FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY 1,2,3,4",
          "claim": "Search's client spans calling geo show a slight rise, 0.408 to 0.412 ms average, with 1476 calls in the abnormal period."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'N' p, service_name, span_name, count(*) n, round(avg(duration)/1e6,3) avg_ms, round(quantile_cont(duration,0.9)/1e6,3) p90 FROM normal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2,3 UNION ALL SELECT 'A', service_name, span_name, count(*), round(avg(duration)/1e6,3), round(quantile_cont(duration,0.9)/1e6,3) FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1,2,3",
          "claim": "Frontend /hotels, which depends on search, is essentially unchanged: average 8.25 ms in both periods, p90 about 17 ms."
        }
      ]
    }
  ]
}
